mapper.sql:
where 1=1

		and cppd_llave = #{llaveTabla}


		and cppd_estado = #{estado}


		and cppd_propiedadvalor = #{propiedadValor}


		and cppd_tipo = #{tipo}


		and cppd_campo = #{campo}


		and cppd_texto = #{texto}


		and dppd_fechadefinicion >= #{fechaDefinicionMin}


		and dppd_fechadefinicion  <   #{fechaDefinicionMax}


		and dppd_fechaeliminacion >= #{fechaEliminacionMin}


		and dppd_fechaeliminacion  <   #{fechaEliminacionMax}


		and cppd_usuariocreacion = #{usuarioCreacion}


		and cppd_usuarioeliminacion = #{usuarioEliminacion}


		and cppd_rol = #{rol}


		and cppd_rolexcluyente = #{rolExcluyente}


		and dppd_fechainicial >= #{fechaInicialMin}


		and dppd_fechainicial  <   #{fechaInicialMax}


		and dppd_fechafinal >= #{fechaFinalMin}


		and dppd_fechafinal  <   #{fechaFinalMax}


		and cppd_usuario = #{usuario}


		and cppd_usuarioexcluyente = #{usuarioExcluyente}


		and cppd_bloqueo = #{bloqueo}


		and cppd_motivo = #{motivo}


		and cppd_valor = #{valor}


		and ((select upper(cpvd_nombre) from propiedadvalordefinido_pvdp where cpvd_llave = cppd_propiedadvalor) like upper('%' || #{filtroParametro} || '%'))

mapper.select:
insert into propiedad_ppdp(
	cppd_llave

	,cppd_propiedadvalor


	,cppd_tipo


	,cppd_campo


	,cppd_valor


	,cppd_texto


	,dppd_fechadefinicion


	,dppd_fechaeliminacion


	,cppd_usuariocreacion


	,cppd_usuarioeliminacion


	,cppd_rol


	,cppd_rolexcluyente


	,dppd_fechainicial


	,dppd_fechafinal


	,cppd_usuario


	,cppd_usuarioexcluyente


	,cppd_motivo


	,cppd_bloqueo


	,cppd_estado

) values (
	#{llaveTabla}

	,#{propiedadValor}


	,#{tipo}


	,#{campo}


	,#{valor}


	,#{texto}


	,#{fechaDefinicion}


	,#{fechaEliminacion}


	,#{usuarioCreacion}


	,#{usuarioEliminacion}


	,#{rol}


	,#{rolExcluyente}


	,#{fechaInicial}


	,#{fechaFinal}


	,#{usuario}


	,#{usuarioExcluyente}


	,#{motivo}


	,#{bloqueo}


	,#{estado}

)

CREATE OR REPLACE FUNCTION propiedad_${llaveTabla}(documento character varying, modificador character varying, token character varying) RETURNS character varying AS
$BODY$
${valor}
$BODY$
LANGUAGE plpgsql VOLATILE
COST 100;

